# 依 dW、db、dWq、dWk、dWv、dWo、dbias、dWhy、dby 行序累加平方和求
# 全局范数；任一梯度非有限即失败。平方和溢出（梯度本身均有限）时不
# 再误报失败：取 a=max|g|，同序自 0.0 累加 q+=(g/a)**2，以
# (g/a)*(5.0/sqrt(q)) 为裁剪梯度；未溢出路径与原先逐字节一致。
groups = (dW, db, dWq, dWk, dWv, dWo, dbias, dWhy, dby)
sum_sq = 0.0
max_abs = 0.0
overflowed = False
for group in groups:
    rows = group if type(group[0]) is list else (group,)
    for row in rows:
        for v in row:
            if not math.isfinite(v):
                raise ValueError("gradient is non-finite")
            av = abs(v)
            if av > max_abs:
                max_abs = av
            if not overflowed:
                sum_sq += v * v
                if not math.isfinite(sum_sq):
                    overflowed = True

if overflowed:
    # 同序自 0.0 累加 q+=(g/a)**2；max_abs>0（否则平方和不会溢出），
    # 每项 (g/a)**2<=1，q 必有限。
    q = 0.0
    for group in groups:
        rows = group if type(group[0]) is list else (group,)
        for row in rows:
            for v in row:
                r = v / max_abs
                q += r * r
    rescale = 5.0 / math.sqrt(q)

    def _clip(grad):
        return (grad / max_abs) * rescale
else:
    global_norm = math.sqrt(sum_sq)
    scale = 5.0 / global_norm if global_norm > 5.0 else 1.0

    def _clip(grad):
        return grad * scale

# 九组参数减 0.1 倍（裁剪后的）梯度；heads、h0、c0 不变。结果非有限
# 即失败。
def _updated(old, grad):
    value = float(old) - 0.1 * _clip(grad)
    if not math.isfinite(value):
        raise ValueError("updated parameter became non-finite")
    return value

